sealed class CreateBillEvent { object BackClick : CreateBillEvent() object ContinueClick : CreateBillEvent() data class AmountChange(val amount: String) : CreateBillEvent() data class DescriptionChange(val description: String) : CreateBillEvent() data class ExpenseTypeChange(val expenseType: ExpenseType) : CreateBillEvent() data class ExpiryDateChange(val date: LocalDate) : CreateBillEvent() }
