@Composable private fun animateFadeAndScaleSnackBar(): Pair<Float, Float> { val alpha by animateFloatAsState( targetValue = 1f, animationSpec = tween( durationMillis = SnackBarConstants.ALPHA_DURATION, easing = FastOutSlowInEasing ), label = "alpha" ) val scale by animateFloatAsState( targetValue = 1f, animationSpec = tween( durationMillis = SnackBarConstants.SCALE_DURATION, easing = FastOutSlowInEasing ), label = "scale" ) return alpha to scale }
private object SnackBarConstants { val PADDING = 8.dp val CONTENT_PADDING = 12.dp val CORNER_RADIUS = 12.dp val ICON_SIZE = 24.dp val ICON_PADDING = 8.dp val SPACING = 8.dp val BUTTON_HEIGHT = 36.dp val MESSAGE_FONT_SIZE = 14.sp val ACTION_FONT_SIZE = 14.sp const val ALPHA_DURATION = 250 const val SCALE_DURATION = 200 }
enum class SnackBarType { SUCCESS, ERROR, WARNING, INFO }
@Composable fun GradientSnackBar( type: SnackBarType, message: String, modifier: Modifier = Modifier, actionLabel: String? = "Đóng", onAction: () -> Unit = {}, ) { val (alphaAnim, scaleAnim) = animateFadeAndScaleSnackBar() // Box( // modifier = Modifier.fillMaxSize() // ) { // // Box( // modifier = Modifier // .align(Alignment.BottomCenter) // .padding(bottom = 16.dp) // ) { Card( modifier = modifier .fillMaxWidth(0.9f) .wrapContentHeight() .alpha(alphaAnim) .scale(scaleAnim) .padding(SnackBarConstants.PADDING), shape = RoundedCornerShape(SnackBarConstants.CORNER_RADIUS), colors = CardDefaults.cardColors(containerColor = Color.Transparent), elevation = CardDefaults.cardElevation(defaultElevation = 6.dp) ) { Row( modifier = Modifier .background( Brush.linearGradient( colors = when (type) { SnackBarType.SUCCESS -> SuccessGradient SnackBarType.ERROR -> ErrorGradient SnackBarType.WARNING -> WarningGradient SnackBarType.INFO -> InfoGradient } ) ) .padding(SnackBarConstants.CONTENT_PADDING) .height(IntrinsicSize.Min), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween ) { Row( verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f) ) { when (type) { SnackBarType.SUCCESS -> Icon( painter = painterResource(R.drawable.success), contentDescription = null, tint = Color.White, modifier = Modifier .size(SnackBarConstants.ICON_SIZE) .padding(end = SnackBarConstants.ICON_PADDING) )
else -> Icon( imageVector = Icons.Rounded.Info, contentDescription = null, tint = Color.White, modifier = Modifier .size(SnackBarConstants.ICON_SIZE) .padding(end = SnackBarConstants.ICON_PADDING) ) } Text( text = message, color = Color.White, fontSize = SnackBarConstants.MESSAGE_FONT_SIZE, textAlign = TextAlign.Start, lineHeight = SnackBarConstants.MESSAGE_FONT_SIZE * 1.2f, modifier = Modifier.padding(end = SnackBarConstants.SPACING) ) } actionLabel?.let { TextButton( onClick = onAction, modifier = Modifier.height(SnackBarConstants.BUTTON_HEIGHT) ) { Text( text = it, color = Color.White, fontSize = SnackBarConstants.ACTION_FONT_SIZE, fontWeight = FontWeight.Medium ) } } } } // } // } }
