@Composable fun CustomSwitchButton( switchPadding: Dp = 4.dp, buttonWidth: Dp = 60.dp, buttonHeight: Dp = 30.dp, value: Boolean, onClick: () -> Unit ) {
val switchSize by remember { mutableStateOf(buttonHeight - switchPadding * 2) }
val interactionSource = remember { MutableInteractionSource() }
var padding by remember { mutableStateOf(0.dp) }
padding = if (value) buttonWidth - switchSize - switchPadding * 2 else 0.dp
val animateSize by animateDpAsState( targetValue = if (value) padding else 0.dp, tween( durationMillis = 700, delayMillis = 0, easing = LinearOutSlowInEasing ) )
Box( modifier = Modifier .width(buttonWidth) .height(buttonHeight) .clip(CircleShape) .background(if (value) Green1 else Color.LightGray) .clickable( interactionSource = interactionSource, indication = null ) {
onClick()
} ) { Row( modifier = Modifier .fillMaxSize() .padding(switchPadding) ) {
Box( modifier = Modifier .fillMaxHeight() .width(animateSize) .background(Color.Transparent) )
Box( modifier = Modifier .size(switchSize) .clip(CircleShape) .background(Color.White) )
} }
}
