val months = listOf( "Tháng 1", "Tháng 2", "Tháng 3", "Tháng 4", "Tháng 5", "Tháng 6", "Tháng 7", "Tháng 8", "Tháng 9", "Tháng 10", "Tháng 11", "Tháng 12" )
val minYear = minDate.year val maxYear = maxDate.year
Column( modifier = Modifier .fillMaxWidth() .background( color = White1, shape = RoundedCornerShape(20.dp) ) .padding(20.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(16.dp) ) { // Header Text( text = "Chọn tháng và năm", style = AppTypography.bodyLarge.copy( fontWeight = FontWeight.Bold ), color = Black1 )
// Year selector Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { IconButton( onClick = { if (selectedYear > minYear) selectedYear-- }, enabled = selectedYear > minYear ) { Icon( painter = painterResource(R.drawable.arrow_left), contentDescription = "Previous year", tint = if (selectedYear > minYear) Blue1 else Gray1 ) }
Text( text = "Năm $selectedYear", style = AppTypography.bodyLarge.copy( fontWeight = FontWeight.SemiBold ), color = Blue1 )
IconButton( onClick = { if (selectedYear < maxYear) selectedYear++ }, enabled = selectedYear < maxYear ) { Icon( painter = painterResource(R.drawable.arrow_right), contentDescription = "Next year", tint = if (selectedYear < maxYear) Blue1 else Gray1 ) } }
// Month grid LazyVerticalGrid( columns = GridCells.Fixed(3), modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp), verticalArrangement = Arrangement.spacedBy(10.dp) ) { items(12) { index -> val monthValue = index + 1 val isSelected = selectedMonth == monthValue val isEnabled = isMonthEnabled(selectedYear, monthValue, minDate, maxDate)
Box( modifier = Modifier .aspectRatio(1.5f) .background( color = when { isSelected -> Blue1 !isEnabled -> Gray2.copy(alpha = 0.3f) else -> Blue6.copy(alpha = 0.3f) }, shape = RoundedCornerShape(12.dp) ) .border( width = if (isSelected) 2.dp else 0.dp, color = if (isSelected) Blue3 else Color.Transparent, shape = RoundedCornerShape(12.dp) ) .then( if (isEnabled) { Modifier.customClick( onClick = { selectedMonth = monthValue }, shape = RoundedCornerShape(12.dp) ) } else { Modifier } ), contentAlignment = Alignment.Center ) { Text( text = months[index], style = AppTypography.bodyMedium.copy( fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal ), color = when { isSelected -> White1 !isEnabled -> Gray1 else -> Black1 } ) } } }
