private fun isMonthEnabled( year: Int, month: Int, minDate: LocalDate, maxDate: LocalDate ): Boolean { val date = LocalDate.of(year, month, 1) val minYearMonth = LocalDate.of(minDate.year, minDate.monthValue, 1) val maxYearMonth = LocalDate.of(maxDate.year, maxDate.monthValue, 1) return !date.isBefore(minYearMonth) && !date.isAfter(maxYearMonth) }
