@Composable fun CustomSwitchButton( switchPadding: Dp = 4.dp, buttonWidth: Dp = 60.dp, buttonHeight: Dp = 30.dp, value: Boolean, onClick: () -> Unit ) {
val switchSize by remember { mutableStateOf(buttonHeight - switchPadding * 2) }
val interactionSource = remember { MutableInteractionSource() }
var padding by remember { mutableStateOf(0.dp) }
padding = if (value) buttonWidth - switchSize - switchPadding * 2 else 0.dp
val animateSize by animateDpAsState( targetValue = if (value) padding else 0.dp, tween( durationMillis = 700, delayMillis = 0, easing = LinearOutSlowInEasing ) )
Box( modifier = Modifier .width(buttonWidth) .height(buttonHeight) .clip(CircleShape) .background(if (value) Green1 else Color.LightGray) .clickable( interactionSource = interactionSource, indication = null ) {
onClick()
} ) { Row( modifier = Modifier .fillMaxSize() .padding(switchPadding) ) {
Box( modifier = Modifier .fillMaxHeight() .width(animateSize) .background(Color.Transparent) )
Box( modifier = Modifier .size(switchSize) .clip(CircleShape) .background(Color.White) )
} }
}
@Composable fun Example2Page( close: () -> Unit = {}, dateSelected: (startDate: LocalDate, endDate: LocalDate) -> Unit = { _, _ -> }, ) { val currentMonth = remember { YearMonth.now() } val startMonth = remember { currentMonth } val endMonth = remember { currentMonth.plusMonths(12) } val today = remember { LocalDate.now() } var selection by remember { mutableStateOf( DateSelection( startDate = LocalDate.now().plusDays(1), endDate = LocalDate.now().plusDays(3) ) ) } val daysOfWeek = remember { daysOfWeek() } MaterialTheme(colorScheme = MaterialTheme.colorScheme.copy(primary = Blue1)) { Box( modifier = Modifier .fillMaxSize() .background(Color.White) .padding(10.dp), ) { Column { val state = rememberCalendarState( startMonth = startMonth, endMonth = endMonth, firstVisibleMonth = currentMonth, firstDayOfWeek = daysOfWeek.first(), ) CalendarTop( daysOfWeek = daysOfWeek, selection = selection, close = close, clearDates = { selection = DateSelection() }, ) VerticalCalendar( state = state, contentPadding = PaddingValues(bottom = 100.dp), dayContent = { value ->
Day( value, today = today, selection = selection, isInMonth = value.position == DayPosition.MonthDate, ) { day -> if (day.position == DayPosition.MonthDate && (day.date == today || day.date.isAfter(today)) ) { selection = getSelection( clickedDate = day.date, dateSelection = selection, ) } } }, monthHeader = { month -> MonthHeader(month) }, ) } CalendarBottom( modifier = Modifier .wrapContentHeight() .fillMaxWidth() .background(Color.White) .align(Alignment.BottomCenter), selection = selection, save = { val (startDate, endDate) = selection if (startDate != null && endDate != null) { dateSelected(startDate, endDate) } }, ) } } }
