Box( modifier = Modifier .aspectRatio(1f) // This is important for square-sizing! .clickable( enabled = day.position == DayPosition.MonthDate && day.date >= today, onClick = { onClick(day) }, ) .backgroundHighlight( day = day, today = today, selection = selection, ) { textColor = it }, contentAlignment = Alignment.Center, ) { Text( text = day.date.dayOfMonth.toString(), color = if (isInMonth) textColor else Gray1.copy(0.8f), fontSize = 16.sp, fontWeight = FontWeight.Medium, ) } }
