@Composable fun CustomDatePicker( minDate: LocalDate, maxDate: LocalDate, initialDate: LocalDate = LocalDate.now(), onSelectedDate: (LocalDate) -> Unit, onDismiss: () -> Unit ) { // ── ViewMode: CALENDAR | YEAR_PICKER | MONTH_PICKER ───────────────── enum class DatePickerMode { CALENDAR, YEAR_PICKER, MONTH_PICKER }
val today = LocalDate.now() var selectedDate by remember { mutableStateOf(initialDate) } var displayedYearMonth by remember { mutableStateOf( when { initialDate < minDate -> minDate initialDate > maxDate -> maxDate else -> initialDate }.withDayOfMonth(1) ) } var mode by remember { mutableStateOf(DatePickerMode.CALENDAR) }
val vietnameseMonths = listOf( "Tháng 1", "Tháng 2", "Tháng 3", "Tháng 4", "Tháng 5", "Tháng 6", "Tháng 7", "Tháng 8", "Tháng 9", "Tháng 10", "Tháng 11", "Tháng 12" ) val dayHeaders = listOf("CN", "T2", "T3", "T4", "T5", "T6", "T7")
val minYear = minDate.year val maxYear = maxDate.year val years = (minYear..maxYear).toList()
val canGoPrev = displayedYearMonth.isAfter(minDate.withDayOfMonth(1)) val canGoNext = displayedYearMonth.isBefore(maxDate.withDayOfMonth(1))
val firstDayOfMonth = displayedYearMonth val daysInMonth = firstDayOfMonth.lengthOfMonth() val firstDowValue = firstDayOfMonth.dayOfWeek.value % 7 val totalCells = firstDowValue + daysInMonth
Column( modifier = Modifier .fillMaxWidth() .background(color = White1, shape = RoundedCornerShape(20.dp)) .padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp) ) { // ── Header ────────────────────────────────────────────────────── Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { // Nút prev — ẩn khi ở year/month picker IconButton( onClick = { if (canGoPrev) displayedYearMonth = displayedYearMonth.minusMonths(1) }, enabled = canGoPrev && mode == DatePickerMode.CALENDAR ) { Icon( painter = painterResource(R.drawable.arrow_left), contentDescription = "Tháng trước", tint = if (canGoPrev && mode == DatePickerMode.CALENDAR) Blue1 else Color.Transparent, modifier = Modifier.size(20.dp) ) }
// Tháng & Năm — click để mở picker tương ứng Row( horizontalArrangement = Arrangement.spacedBy(6.dp), verticalAlignment = Alignment.CenterVertically ) { // Chip Tháng Box( modifier = Modifier .background( color = if (mode == DatePickerMode.MONTH_PICKER) Blue1 else Blue1.copy(alpha = 0.08f), shape = RoundedCornerShape(8.dp) ) .clickable( indication = null, interactionSource = remember { MutableInteractionSource() } ) { mode = if (mode == DatePickerMode.MONTH_PICKER) DatePickerMode.CALENDAR else DatePickerMode.MONTH_PICKER } .padding(horizontal = 10.dp, vertical = 4.dp) ) { Text( text = vietnameseMonths[displayedYearMonth.monthValue - 1], style = AppTypography.bodyMedium.copy(fontWeight = FontWeight.Bold), color = if (mode == DatePickerMode.MONTH_PICKER) White1 else Blue1 ) }
// Chip Năm Box( modifier = Modifier .background( color = if (mode == DatePickerMode.YEAR_PICKER) Blue1 else Blue1.copy(alpha = 0.08f), shape = RoundedCornerShape(8.dp) ) .clickable( indication = null, interactionSource = remember { MutableInteractionSource() } ) { mode = if (mode == DatePickerMode.YEAR_PICKER) DatePickerMode.CALENDAR else DatePickerMode.YEAR_PICKER } .padding(horizontal = 10.dp, vertical = 4.dp) ) { Text( text = displayedYearMonth.year.toString(), style = AppTypography.bodyMedium.copy(fontWeight = FontWeight.Bold), color = if (mode == DatePickerMode.YEAR_PICKER) White1 else Blue1 ) } }
// Nút next IconButton( onClick = { if (canGoNext) displayedYearMonth = displayedYearMonth.plusMonths(1) }, enabled = canGoNext && mode == DatePickerMode.CALENDAR ) { Icon( painter = painterResource(R.drawable.arrow_right), contentDescription = "Tháng sau", tint = if (canGoNext && mode == DatePickerMode.CALENDAR) Blue1 else Color.Transparent, modifier = Modifier.size(20.dp) ) } }
// ── Year Picker ────────────────────────────────────────────────── if (mode == DatePickerMode.YEAR_PICKER) { LazyVerticalGrid( columns = GridCells.Fixed(4), modifier = Modifier .fillMaxWidth() .height(200.dp), horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp) ) { items(years.size) { index -> val year = years[index] val isSelected = year == displayedYearMonth.year val isInRange = year in minYear..maxYear Box( modifier = Modifier .aspectRatio(1.8f) .background( color = if (isSelected) Blue1 else if (year == today.year) Blue1.copy(alpha = 0.08f) else Color.Transparent, shape = RoundedCornerShape(8.dp) ) .then( if (isInRange) Modifier.clickable( indication = null, interactionSource = remember { MutableInteractionSource() } ) { displayedYearMonth = displayedYearMonth.withYear(year) .let { ym -> // giữ tháng trong phạm vi when { ym.isBefore(minDate.withDayOfMonth(1)) -> minDate.withDayOfMonth(1) ym.isAfter(maxDate.withDayOfMonth(1)) -> maxDate.withDayOfMonth(1) else -> ym } } mode = DatePickerMode.CALENDAR } else Modifier ) .padding(4.dp), contentAlignment = Alignment.Center ) { Text( text = year.toString(), style = AppTypography.bodySmall.copy( fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal ), color = when { isSelected -> White1 !isInRange -> Gray2 else -> Black1 } ) } } } }
// ── Month Picker ───────────────────────────────────────────────── if (mode == DatePickerMode.MONTH_PICKER) { LazyVerticalGrid( columns = GridCells.Fixed(3), modifier = Modifier .fillMaxWidth() .height(180.dp), horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp) ) { items(12) { index -> val monthNum = index + 1 val monthDate = displayedYearMonth.withMonth(monthNum) val isSelected = monthNum == displayedYearMonth.monthValue val isEnabled = !monthDate.isBefore(minDate.withDayOfMonth(1)) && !monthDate.isAfter(maxDate.withDayOfMonth(1)) val isCurrentMonth = monthNum == today.monthValue && displayedYearMonth.year == today.year Box( modifier = Modifier .height(44.dp) .background( color = if (isSelected) Blue1 else if (isCurrentMonth) Blue1.copy(alpha = 0.08f) else Color.Transparent, shape = RoundedCornerShape(8.dp) ) .then( if (isEnabled) Modifier.clickable( indication = null, interactionSource = remember { MutableInteractionSource() } ) { displayedYearMonth = displayedYearMonth.withMonth(monthNum) mode = DatePickerMode.CALENDAR } else Modifier ) .padding(4.dp), contentAlignment = Alignment.Center ) { Text( text = "T$monthNum", style = AppTypography.bodySmall.copy( fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal ), color = when { isSelected -> White1 !isEnabled -> Gray2 else -> Black1 } ) } } } }
// ── Calendar view ──────────────────────────────────────────────── if (mode == DatePickerMode.CALENDAR) { // Tên thứ Row(modifier = Modifier.fillMaxWidth()) { dayHeaders.forEach { label -> Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.Center) { Text( text = label, style = AppTypography.bodySmall.copy(fontWeight = FontWeight.SemiBold), color = if (label == "CN") Color(0xFFE53935) else Gray1 ) } } }
// Lưới ngày val rows = (totalCells + 6) / 7 Column(verticalArrangement = Arrangement.spacedBy(4.dp)) { for (row in 0 until rows) { Row(modifier = Modifier.fillMaxWidth()) { for (col in 0 until 7) { val cellIndex = row * 7 + col val dayNumber = cellIndex - firstDowValue + 1 val cellDate = if (dayNumber in 1..daysInMonth) displayedYearMonth.withDayOfMonth(dayNumber) else null
val isEnabled = cellDate != null && !cellDate.isBefore(minDate) && !cellDate.isAfter(maxDate) val isSelected = cellDate == selectedDate val isToday = cellDate == today
Box( modifier = Modifier .weight(1f) .aspectRatio(1f) .padding(2.dp) .then( if (isSelected) Modifier.background(Blue1, CircleShape) else if (isToday && isEnabled) Modifier.border(1.5.dp, Blue1, CircleShape) else Modifier ) .then( if (isEnabled) Modifier.clickable( indication = null, interactionSource = remember { MutableInteractionSource() } ) { selectedDate = cellDate!! } else Modifier ), contentAlignment = Alignment.Center ) { if (cellDate != null) { Text( text = dayNumber.toString(), style = AppTypography.bodySmall.copy( fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal ), color = when { isSelected -> White1 !isEnabled -> Gray2 col == 0 -> Color(0xFFE53935) else -> Black1 } ) } } } } } } }
// ── Chú thích ngày đã chọn ─────────────────────────────────────── if (selectedDate in minDate..maxDate) { Text( text = "Đã chọn: ${selectedDate.dayOfMonth}/${selectedDate.monthValue}/${selectedDate.year}", style = AppTypography.bodySmall, color = Blue1, modifier = Modifier.align(Alignment.CenterHorizontally) ) }
// ── Buttons ────────────────────────────────────────────────────── Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp) ) { TextButton( onClick = onDismiss, modifier = Modifier.weight(1f), colors = androidx.compose.material3.ButtonDefaults.textButtonColors(contentColor = Gray1) ) { Text("Hủy", style = AppTypography.bodyMedium) } Button( onClick = { onSelectedDate(selectedDate) }, modifier = Modifier.weight(1f), enabled = selectedDate in minDate..maxDate, shape = RoundedCornerShape(10.dp), colors = androidx.compose.material3.ButtonDefaults.buttonColors( containerColor = Blue1, contentColor = White1, disabledContainerColor = Gray2, disabledContentColor = White1 ) ) { Text("Xác nhận", style = AppTypography.bodyMedium) } } } }
@Composable fun CustomMonthYearPicker( initialDate: LocalDate = LocalDate.now(), minDate: LocalDate = LocalDate.now().minusYears(10), maxDate: LocalDate = LocalDate.now().plusYears(10), onSelectedDate: (LocalDate) -> Unit, onDismiss: () -> Unit ) { var selectedYear by remember { mutableStateOf(initialDate.year) } var selectedMonth by remember { mutableStateOf(initialDate.monthValue) }
val months = listOf( "Tháng 1", "Tháng 2", "Tháng 3", "Tháng 4", "Tháng 5", "Tháng 6", "Tháng 7", "Tháng 8", "Tháng 9", "Tháng 10", "Tháng 11", "Tháng 12" )
val minYear = minDate.year val maxYear = maxDate.year
Column( modifier = Modifier .fillMaxWidth() .background( color = White1, shape = RoundedCornerShape(20.dp) ) .padding(20.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(16.dp) ) { // Header Text( text = "Chọn tháng và năm", style = AppTypography.bodyLarge.copy( fontWeight = FontWeight.Bold ), color = Black1 )
// Year selector Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { IconButton( onClick = { if (selectedYear > minYear) selectedYear-- }, enabled = selectedYear > minYear ) { Icon( painter = painterResource(R.drawable.arrow_left), contentDescription = "Previous year", tint = if (selectedYear > minYear) Blue1 else Gray1 ) }
Text( text = "Năm $selectedYear", style = AppTypography.bodyLarge.copy( fontWeight = FontWeight.SemiBold ), color = Blue1 )
IconButton( onClick = { if (selectedYear < maxYear) selectedYear++ }, enabled = selectedYear < maxYear ) { Icon( painter = painterResource(R.drawable.arrow_right), contentDescription = "Next year", tint = if (selectedYear < maxYear) Blue1 else Gray1 ) } }
// Month grid LazyVerticalGrid( columns = GridCells.Fixed(3), modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp), verticalArrangement = Arrangement.spacedBy(10.dp) ) { items(12) { index -> val monthValue = index + 1 val isSelected = selectedMonth == monthValue val isEnabled = isMonthEnabled(selectedYear, monthValue, minDate, maxDate)
Box( modifier = Modifier .aspectRatio(1.5f) .background( color = when { isSelected -> Blue1 !isEnabled -> Gray2.copy(alpha = 0.3f) else -> Blue6.copy(alpha = 0.3f) }, shape = RoundedCornerShape(12.dp) ) .border( width = if (isSelected) 2.dp else 0.dp, color = if (isSelected) Blue3 else Color.Transparent, shape = RoundedCornerShape(12.dp) ) .then( if (isEnabled) { Modifier.customClick( onClick = { selectedMonth = monthValue }, shape = RoundedCornerShape(12.dp) ) } else { Modifier } ), contentAlignment = Alignment.Center ) { Text( text = months[index], style = AppTypography.bodyMedium.copy( fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal ), color = when { isSelected -> White1 !isEnabled -> Gray1 else -> Black1 } ) } } }
// Action buttons // Row( // modifier = Modifier.fillMaxWidth(), // horizontalArrangement = Arrangement.spacedBy(10.dp, Alignment.CenterHorizontally) // ) { // Row( // // modifier = Modifier // .weight(1f) // .customClick(onClick = onDismiss) // ) { // Text( // text = "Hủy", // color = Black1, // style = AppTypography.bodyMedium // ) // } // // TextButton( // onClick = { // val selectedDate = LocalDate.of(selectedYear, selectedMonth, 1) // onSelectedDate(selectedDate) // }, // modifier = Modifier // .weight(1f) // .background( // color = Blue1, // shape = RoundedCornerShape(12.dp) // ) // ) { // Text( // text = "Xác nhận", // color = White1, // style = AppTypography.bodyMedium.copy( // fontWeight = FontWeight.Bold // ) // ) // } // } Row( modifier = Modifier .fillMaxWidth() .padding(horizontal = 10.dp), horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically ) { Row( modifier = Modifier .weight(1f) .clickable { onDismiss() } .padding(vertical = 10.dp), horizontalArrangement = Arrangement.Center, ) { Text( text = "Hủy", style = AppTypography.bodyMedium.copy( fontWeight = FontWeight.Bold ), color = Blue5 ) } Row( modifier = Modifier .weight(1f) .background( color = Blue5, shape = RoundedCornerShape(10.dp) ) .shadow( elevation = 10.dp, shape = RoundedCornerShape(10.dp), ambientColor = Color.Transparent, spotColor = Color.Transparent ) .clickable { val selectedDate = LocalDate.of(selectedYear, selectedMonth, 1) onSelectedDate(selectedDate) } .padding(vertical = 10.dp), horizontalArrangement = Arrangement.Center, ) { Text( text = "Xác nhận", style = AppTypography.bodyMedium.copy( fontWeight = FontWeight.Bold ), color = White1 ) } } } }
private fun isMonthEnabled( year: Int, month: Int, minDate: LocalDate, maxDate: LocalDate ): Boolean { val date = LocalDate.of(year, month, 1) val minYearMonth = LocalDate.of(minDate.year, minDate.monthValue, 1) val maxYearMonth = LocalDate.of(maxDate.year, maxDate.monthValue, 1) return !date.isBefore(minYearMonth) && !date.isAfter(maxYearMonth) }
