@Composable fun ProgressBarWithLabel( progress: Float, modifier: Modifier = Modifier, progressColor: Color = Color(0xFF00BCD4), backgroundColor: Color = Color(0xFFE0E0E0), labelBackgroundColor: Color = Color.White, labelBorderColor: Color = Color(0xFF9E9E9E), labelTextColor: Color = Color.Black, progressHeight: Dp = 8.dp, animationDuration: Int = 1000 ) { val animatedProgress by animateFloatAsState( targetValue = progress.coerceIn(0f, 1f), animationSpec = tween(durationMillis = animationDuration, easing = EaseInOut), label = "progress" )
val percentage = (animatedProgress * 100).toInt()
// Keep measured widths in px val progressBarWidthPx = remember { mutableStateOf(0) } val labelWidthPx = remember { mutableStateOf(0) }
Box( modifier = modifier .fillMaxWidth() .height(progressHeight + 40.dp) ) { // Background bar - measure its width Box( modifier = Modifier .fillMaxWidth() .height(progressHeight) .align(Alignment.CenterStart) .onGloballyPositioned { coordinates -> progressBarWidthPx.value = coordinates.size.width } .clip(RoundedCornerShape(progressHeight / 2)) .background(backgroundColor) )
// Progress fill Box( modifier = Modifier .fillMaxWidth(animatedProgress) .height(progressHeight) .align(Alignment.CenterStart) .clip(RoundedCornerShape(progressHeight / 2)) .background( brush = Brush.horizontalGradient( colors = listOf( progressColor, progressColor.copy(alpha = 0.8f) ) ) ) )
// Compute offset for label: center it at (animatedProgress * barWidth) val offsetXDp = with(LocalDensity.current) { if (progressBarWidthPx.value == 0) { 0.dp } else { // desired center in px val desiredCenterPx = animatedProgress * progressBarWidthPx.value // label width in px (may be 0 until measured) val lw = labelWidthPx.value.toFloat() // compute left x so that label is centered on desiredCenterPx var leftPx = desiredCenterPx - lw / 2f // clamp to stay inside the progress bar val maxLeftPx = (progressBarWidthPx.value - lw).toFloat().coerceAtLeast(0f) leftPx = leftPx.coerceIn(0f, maxLeftPx) leftPx.toDp() } }
Box( modifier = Modifier .align(Alignment.CenterStart) .offset(x = offsetXDp) ) { Box( modifier = Modifier .onGloballyPositioned { coords -> labelWidthPx.value = coords.size.width } .background( color = labelBackgroundColor, shape = RoundedCornerShape(16.dp) ) .border( width = 1.dp, color = labelBorderColor, shape = RoundedCornerShape(16.dp) ) .padding(horizontal = 12.dp, vertical = 4.dp) ) { Text( text = "$percentage%", style = AppTypography.bodySmall, color = labelTextColor, ) } } } }
