} }
@Composable fun CustomBarChart( data: List<Bars>, modifier: Modifier = Modifier ) { if (data.isEmpty()) { Column( modifier = modifier, horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(10.dp) ) {
Icon( painter = painterResource(id = R.drawable.empty_data), contentDescription = null, tint = Gray1, modifier = Modifier.size(48.dp) ) Spacer(modifier = Modifier.height(20.dp)) Text( text = "Chưa có dữ liệu để thống kê", style = AppTypography.bodyMedium, color = Gray1 ) Text( text = "Hãy phát sinh giao dịch để xem phân bố", style = AppTypography.bodySmall, color = Gray1 ) } } else
ColumnChart( modifier = modifier.height(300.dp), data = data, barProperties = BarProperties( cornerRadius = Bars.Data.Radius.Rectangle(topRight = 6.dp, topLeft = 6.dp), spacing = 1.dp, thickness = 20.dp, ), animationSpec = spring( dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow ), gridProperties = GridProperties( yAxisProperties = GridProperties.AxisProperties( enabled = false, ), ), indicatorProperties = HorizontalIndicatorProperties( contentBuilder = { indicator -> formatterVND(indicator.toLong()) + " VND" }, )
) }
@Composable fun DefaultImageProfile( name: String, modifier: Modifier = Modifier, ) { Row( modifier = modifier
.background( color = Blue5.copy( alpha = 0.3f ), shape = CircleShape ) .clip(CircleShape) .padding(5.dp), horizontalArrangement = Arrangement.Center, verticalAlignment = Alignment.CenterVertically ) { val templateName = name.split(" ") .mapNotNull { it.firstOrNull()?.toString() } .take(2) .joinToString("") Text( templateName, color = Blue1, style = AppTypography.bodySmall ) } }
@Composable fun shimmerBrush(): Brush { val transition = rememberInfiniteTransition(label = "shimmer") val translateAnim = transition.animateFloat( initialValue = 0f, targetValue = 1000f, animationSpec = infiniteRepeatable( animation = tween(1200, easing = LinearEasing), repeatMode = RepeatMode.Restart ), label = "shimmer_anim" )
return Brush.linearGradient( colors = listOf( Color.LightGray.copy(alpha = 0.6f), Color.LightGray.copy(alpha = 0.3f), Color.LightGray.copy(alpha = 0.6f), ), start = Offset(translateAnim.value - 1000f, 0f), end = Offset(translateAnim.value, 0f) ) }
@Composable fun SkeletonBox( modifier: Modifier = Modifier, shape: Shape = RoundedCornerShape(8.dp) ) { Box( modifier = modifier .background( brush = shimmerBrush(), shape = shape ) ) }
@Composable fun Modifier.shimmerEffect(): Modifier { val brush = shimmerBrush() return this.background(brush) }
@Composable @Preview() fun Preview() { ProgressBarWithLabel( 0.2f )
}
